// elkLayout — left-to-right graph layout for the topology canvas, backed
// by ELK's `layered` algorithm. Replaces the previous dagre layout.
//
// Why ELK: the dashboard must stay usable at 1000+ nodes (controllers +
// modules + services). The graph is rendered with hierarchical drill-down,
// so at any moment ELK only lays out the VISIBLE subgraph (tens to low
// hundreds of nodes) — which keeps a main-thread layout fast enough that a
// web worker isn't needed yet. ELK also supports nested/compound layouts
// (`elk.hierarchyHandling`), which the drill-down clusters use later.
//
// ELK runs on the MAIN THREAD here: the dashboard is bundled by nexus's own
// esbuild-in-Go pipeline (no Vite), so the Vite `new URL(...worker...)`
// trick is unavailable. `elk.layout()` is still async (Promise), so the
// call site stays async-ready and a worker can drop in later without
// touching callers.
import ELK from 'elkjs/lib/elk.bundled.js'
import { Position } from '@vue-flow/core'

const elk = new ELK()

// Layered, left-to-right. Spacing values picked to match the old dagre
// feel (generous air between ranks for tall module cards). Disconnected
// components are packed rather than smeared across one giant rank.
const DEFAULT_OPTS = {
  'elk.algorithm': 'layered',
  'elk.direction': 'RIGHT',
  'elk.spacing.nodeNode': '64',
  'elk.layered.spacing.nodeNodeBetweenLayers': '140',
  'elk.layered.spacing.edgeNodeBetweenLayers': '40',
  'elk.layered.nodePlacement.strategy': 'NETWORK_SIMPLEX',
  'elk.layered.considerModelOrder.strategy': 'NODES_AND_EDGES',
  'elk.separateConnectedComponents': 'true',
  'elk.spacing.componentComponent': '48',
}

// elkLayout positions a flat set of sized nodes. `sized` is
// [{ id, width, height }]; `edges` is [{ source, target }] (parallel edges
// and dangling endpoints are tolerated). Returns Map<id, {x, y}> where x/y
// is the node's TOP-LEFT corner — already Vue Flow's position origin, so no
// center offset is needed (dagre returned centers; ELK does not).
export async function elkLayout(sized, edges, options = {}) {
  if (!sized || sized.length === 0) return new Map()
  const graph = {
    id: 'root',
    layoutOptions: { ...DEFAULT_OPTS, ...options },
    children: sized.map(n => ({ id: n.id, width: n.width, height: n.height })),
    edges: toElkEdges(sized, edges),
  }
  const res = await elk.layout(graph)
  const pos = new Map()
  for (const c of res.children || []) {
    pos.set(c.id, { x: c.x ?? 0, y: c.y ?? 0 })
  }
  return pos
}

// toElkEdges converts Vue Flow edges to ELK's {id, sources, targets} shape.
// It drops edges whose endpoints aren't in the node set (ELK throws on
// dangling refs) and COLLAPSES parallel edges between the same pair — the
// layout only needs one connection per pair, and fewer edges is less work.
function toElkEdges(sized, edges) {
  const ids = new Set(sized.map(n => n.id))
  const seen = new Set()
  const out = []
  let i = 0
  for (const e of edges || []) {
    if (!ids.has(e.source) || !ids.has(e.target)) continue
    const key = e.source + '�' + e.target
    if (seen.has(key)) continue
    seen.add(key)
    out.push({ id: 'elk-e' + i++, sources: [e.source], targets: [e.target] })
  }
  return out
}

// applyPositions maps a Map<id,{x,y}> back onto Vue Flow nodes, preserving
// the LR handle orientation the canvas expects (sources exit right, targets
// enter left). Nodes ELK didn't place fall back to the origin.
export function applyPositions(nodes, pos) {
  return nodes.map(n => {
    const p = pos.get(n.id) || { x: 0, y: 0 }
    return {
      ...n,
      position: { x: p.x, y: p.y },
      targetPosition: Position.Left,
      sourcePosition: Position.Right,
    }
  })
}
