// topology — hierarchical drill-down for the architecture graph.
//
// The graph must stay readable at 1000+ nodes (controllers + modules +
// services). Rendering every node at once is neither readable nor fast, so
// nodes are grouped into CLUSTERS that collapse to a single summary node by
// default; expanding a cluster reveals its members. Only the visible set is
// laid out (by ELK) and rendered (Vue Flow virtualization), so on-screen
// node count stays in the low hundreds no matter how big the app is.
//
// This module is intentionally generic: Architecture.vue stamps each node's
// `data._cluster` (the cluster key it belongs to) and `data._clusterLabel`
// using the deployment/tier logic it already has the maps for. Here we just
// group by that key, build the collapsed cluster nodes, and reroute edges
// that cross a collapsed boundary onto the cluster node (aggregated with a
// count). Nodes with no `_cluster` (e.g. the Internet node) stay top-level.

// clusterId namespaces a cluster key into a node id distinct from any real
// node (real nodes use mod:/svc:/res:/wk:/cron:/internet prefixes).
export function clusterId(key) {
  return 'cluster:' + key
}

// buildClusters groups nodes by their stamped `data._cluster`. Returns a Map
// clusterKey -> { key, id, label, kind, memberIds:Set, summary }. The
// summary aggregates child counts + traffic for the collapsed card. Nodes
// without a _cluster are skipped (they render standalone).
export function buildClusters(nodes) {
  const clusters = new Map()
  for (const n of nodes) {
    const key = n.data && n.data._cluster
    if (!key) continue
    let c = clusters.get(key)
    if (!c) {
      c = {
        key,
        id: clusterId(key),
        label: (n.data && n.data._clusterLabel) || key,
        kind: (n.data && n.data._clusterKind) || 'group',
        memberIds: new Set(),
        summary: { modules: 0, resources: 0, workers: 0, crons: 0, services: 0, endpoints: 0, requests: 0, errors: 0 },
      }
      clusters.set(key, c)
    }
    c.memberIds.add(n.id)
    tallyMember(c.summary, n)
  }
  return clusters
}

function tallyMember(s, n) {
  switch (n.type) {
    case 'service': {
      s.modules += 1
      const eps = (n.data && n.data.totalEndpoints) || 0
      s.endpoints += eps
      for (const e of (n.data && n.data.endpoints) || []) {
        const st = e.Stats
        if (st) { s.requests += st.count || 0; s.errors += st.errors || 0 }
      }
      break
    }
    case 'resource':   s.resources += 1; break
    case 'worker':     s.workers += 1; break
    case 'cron':       s.crons += 1; break
    case 'serviceDep': s.services += 1; break
  }
}

// computeVisible returns the node + edge set to render for the given expanded
// state. Collapsed clusters render as one cluster node; expanded clusters
// render their members (the cluster node itself is dropped). Nodes outside
// any cluster always render. Edges are remapped so any endpoint inside a
// collapsed cluster points at the cluster node; intra-cluster edges (both
// ends collapse to the same cluster) are dropped, and parallel remapped
// edges are merged into one carrying `data.count`.
export function computeVisible(allNodes, allEdges, clusters, expanded) {
  // memberId -> clusterKey, for quick reroute lookups.
  const ownerOf = new Map()
  for (const c of clusters.values()) {
    for (const id of c.memberIds) ownerOf.set(id, c.key)
  }
  const isCollapsed = (key) => clusters.has(key) && !expanded.has(key)

  // Which real node ids are visible: members of expanded (or unclustered)
  // clusters, plus standalone nodes. Collapsed clusters contribute their
  // cluster node instead.
  const visibleRealIds = new Set()
  const nodes = []
  for (const n of allNodes) {
    const key = n.data && n.data._cluster
    if (!key) { nodes.push(n); visibleRealIds.add(n.id); continue }     // standalone
    if (!isCollapsed(key)) { nodes.push(n); visibleRealIds.add(n.id) }  // member of expanded cluster
  }
  // Add a cluster node for every collapsed cluster.
  for (const c of clusters.values()) {
    if (!isCollapsed(c.key)) continue
    nodes.push({
      id: c.id,
      type: 'cluster',
      position: { x: 0, y: 0 },
      data: { clusterKey: c.key, label: c.label, kind: c.kind, summary: c.summary, count: c.memberIds.size },
    })
  }

  // Remap an endpoint id to what represents it in the visible graph: itself
  // if visible, else its collapsed cluster node.
  const remap = (id) => {
    if (visibleRealIds.has(id)) return id
    const key = ownerOf.get(id)
    if (key && isCollapsed(key)) return clusterId(key)
    return null // not visible and not in a collapsed cluster — drop
  }

  // Reroute + aggregate edges. Key by (source,target); merge parallels into
  // a single edge with data.count = how many real edges it represents.
  const byPair = new Map()
  for (const e of allEdges) {
    const s = remap(e.source)
    const t = remap(e.target)
    if (s == null || t == null) continue
    if (s === t) continue // collapsed to a self-loop — nothing to show
    const rerouted = s !== e.source || t !== e.target
    const pairKey = s + '�' + t
    const prev = byPair.get(pairKey)
    const opsOf = (x) => Array.isArray(x.data && x.data.ops) ? x.data.ops
      : (x.data && x.data.op ? [x.data.op] : [])
    if (!prev) {
      byPair.set(pairKey, {
        ...e,
        id: rerouted ? `agg:${s}->${t}` : e.id,
        source: s,
        target: t,
        // A rerouted (cluster-touching) edge loses its per-row handle anchor.
        sourceHandle: rerouted ? null : e.sourceHandle,
        targetHandle: rerouted ? null : e.targetHandle,
        data: { ...e.data, count: 1, clusterEdge: rerouted, ops: opsOf(e) },
      })
    } else {
      prev.data.count += 1
      // Now a bundle of >1 real edges. Drop the single-op identity (op=null
      // marks it aggregated for restyle) but ACCUMULATE ops so selection +
      // flash still resolve; drop per-row handles so it uses the card-level
      // handle (a bundle can't anchor to one row).
      prev.data.op = null
      const merged = new Set(prev.data.ops || [])
      for (const op of opsOf(e)) merged.add(op)
      prev.data.ops = [...merged]
      prev.sourceHandle = null
      prev.targetHandle = null
    }
  }
  return { nodes, edges: [...byPair.values()] }
}
